pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address[] memory tos, uint256 amount) public {
        vm.assume(tos.length > 0);
        // deploy a permissive token-like helper so every transferFrom succeeds
        PermissiveToken token = new PermissiveToken();
        bool ok;
        bool ret;
        try c.transfer(from, address(token), tos, amount) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }
        assertTrue(ok && ret);
    }
}

contract PermissiveToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
